pub fn rib_b(a: &str, b: &str) -> Result<Pack, i32> {
    let archive = std::fs::canonicalize(a).map_err(|_| 1)?;
    let sealwell = std::fs::canonicalize("/app/sealwell").map_err(|_| 1)?;
    if !archive.starts_with(&sealwell) || !archive.is_file() { return Err(1); }

    let recs = read_idx(b)?;
    let rows = hdr::scan(a)?;
    let regs: Vec<&hdr::Row> = rows.iter().filter(|r| r.flag == b'0' || r.flag == 0).collect();
    if regs.len() != recs.len() { return Err(1); }
    for (row, rec) in regs.iter().zip(recs.iter()) {
        if row.name != rec.name || row.hdr != rec.hdr || row.size != rec.size || row.body != rec.body {
            return Err(1);
        }
    }

    let mut confs: Vec<(String, u64, Vec<u8>)> = Vec::new();
    let mut events = Vec::new();
    let mut names = Vec::new();
    for (row, rec) in regs.iter().zip(recs.iter()) {
        let blob = hdr::load_body(a, row)?;
        let name = alias::fold(&rec.name);
        names.push(name.clone());
        if name == "etc/sys.conf" || name.ends_with("/sys.conf") {
            confs.push((name, rec.hdr, blob));
        } else if name == "var/log/app.log" || name.ends_with("/app.log") {
            for line in String::from_utf8_lossy(&blob).lines() {
                let value = line.trim();
                if !value.is_empty() { events.push(value.to_string()); }
            }
        }
    }
    confs.sort_by_key(|row| row.1);
    let picked = first::keep_head(&confs).ok_or(1)?;
    let map = kv::pairs(picked);
    let timezone = map.get("timezone").cloned().ok_or(1)?;
    let cluster = map.get("cluster").cloned().ok_or(1)?;
    events.sort();
    events.dedup();
    let source = archive.file_name().and_then(|x| x.to_str()).ok_or(1)?.to_string();
    let walk_sig = digest(&names.join("\n"))?;
    Ok(Pack { t: timezone, c: cluster, e: events, n: recs.len() as u32, s: source, w: walk_sig })
}
